# Generated by tools/render_packages.py from packaging/homebrew/jai.rb.tmpl in
# https://github.com/matteopolak/jai for release v0.4.3. Do not edit by hand.
class Jai < Formula
  desc "Independent toolchain for the Jai language: compiler, LSP, linter and formatter"
  homepage "https://github.com/matteopolak/jai"
  # Plus the jaic Runtime Library Exception (LICENSE-EXCEPTION), which has no SPDX identifier.
  license "AGPL-3.0-or-later"

  livecheck do
    url :stable
    strategy :github_latest
  end

  # Releases after 0.4.1 have a build for each of these. For 0.4.1 and earlier,
  # tools/render_packages.py gives Intel macOS and arm64 Linux the URL of the nearest build, so the
  # formula still loads there, and adds `depends_on arch:` lines that refuse the install there.
  on_macos do
    on_arm do
      url "https://github.com/matteopolak/jai/releases/download/v0.4.3/jai-macos-arm64.tar.gz"
      sha256 "eba609c2fa8e3bb86b870e57469146b66df1b5f6e03ed2be47d09679704629b2"
    end
    on_intel do
      url "https://github.com/matteopolak/jai/releases/download/v0.4.3/jai-macos-x64.tar.gz"
      sha256 "2f3d468fd9a5fc8a304f6ab9f50b82e2fc75bf4684bafbb7dd0dc332fdcb689f"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/matteopolak/jai/releases/download/v0.4.3/jai-linux-arm64.tar.gz"
      sha256 "4c6974e6d6ebf8a08b795e0c58ef47704381b8e100feced739138b6989c9529e"
    end
    on_intel do
      url "https://github.com/matteopolak/jai/releases/download/v0.4.3/jai-linux-x64.tar.gz"
      sha256 "e20168300f380d818fab5a7364a747c1677b34eed9785fcf1014af45394b19cb"
    end
  end

  def install
    # jaic, jailint and jailsp find stdlib/ (which loads ../prelude/) next to the real file
    # behind the bin/ symlinks, and native libraries (wgpu-native, stb_*, rpmalloc) in
    # ../artifacts/native-libs. Archives up to 0.4.0 have no artifacts/.
    libexec.install "jaic", "jailsp", "jailint", "jaifmt", "stdlib", "prelude"
    libexec.install "artifacts" if File.directory?("artifacts")
    bin.install_symlink libexec/"jaic", libexec/"jailsp", libexec/"jailint", libexec/"jaifmt"
    doc.install "README.md", "CHANGELOG.md"
  end

  test do
    (testpath/"hello.jai").write <<~JAI
      #import "Basic";

      main :: () {
          print("Hello from Homebrew!\\n");
      }
    JAI
    assert_equal "Hello from Homebrew!\n", shell_output("#{bin}/jaic run hello.jai")
    assert_equal "main :: () {\n    x := 1;\n}\n", pipe_output("#{bin}/jaifmt --stdin", "main::(){x:=1;}")
    system bin/"jailint", "hello.jai"
  end
end
